function.arguments:
{"command": "cat > /workspace/main.go << 'GOEOF'
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unicode"
)

const Version = "1.13.0"

type FileEntry struct {
	Name     string
	IsDir    bool
	IsHidden bool
	Size     int64
	Mode     os.FileMode
	ModTime  time.Time
}

type State struct {
	CurrentDir   string
	Files        []FileEntry
	Selected     int
	PreviewMode  bool
	PreviewFile  *FileEntry
	SearchQuery  string
	SearchResults []FileEntry
	SearchIndex  int
	HideHidden   bool
	Border       bool
	Icons        bool
	DirOnly      bool
	ExitWithoutCD bool
}

func main() {
	state := initState()

	// Parse flags
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--icons":
			state.Icons = true
		case "--dir-only":
			state.DirOnly = true
		case "--hide-hidden":
			state.HideHidden = true
		case "--preview":
			state.PreviewMode = true
		case "--with-border":
			state.Border = true
		case "--fuzzy":
			state.SearchQuery = ""
			state.SearchResults = state.Files
			state.SearchIndex = 0
		case "--help":
			printHelp()
			os.Exit(0)
		case "--version":
			fmt.Println("walk version", Version)
			os.Exit(0)
		}
	}

	// Check for TTY
	if !hasTTY() {
		fmt.Println("walk: terminal required")
		os.Exit(1)
	}

	// Load environment variables
	loadEnvVars()

	// Load icons
	loadIcons()

	// Load status bar
	loadStatusBar()

	// Load open with commands
	loadOpenWith()

	// Load remove command
	loadRemoveCmd()

	// Load main color
	loadMainColor()

	// Start the interactive loop
	run(state)
}

func hasTTY() bool {
	return os.IsTerminal(syscall.Stdin)
}

func printHelp() {
	fmt.Println("Walk — a terminal navigator; a cd and ls replacement.")
	fmt.Println()
	fmt.Println("Usage:")
	fmt.Println("  walk [options] [directory]")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("  --icons       Show icons")
	fmt.Println("  --dir-only    Show dirs only")
	fmt.Println("  --hide-hidden Hide hidden files")
	fmt.Println("  --preview     Start with preview mode on")
	fmt.Println("  --with-border Show border in preview mode")
	fmt.Println("  --fuzzy       Start with fuzzy search on")
	fmt.Println("  --help        Show this help message")
	fmt.Println("  --version     Show version")
	fmt.Println()
	fmt.Println("Key bindings:")
	fmt.Println("  arrows, hjkl: Move cursor")
	fmt.Println("  shift + arrows: Jump to start/end")
	fmt.Println("  Enter: Enter directory")
	fmt.Println("  Backspace: Exit directory")
	fmt.Println("  Space: Toggle preview")
	fmt.Println("  Esc, q: Exit with cd")
	fmt.Println("  Ctrl+C: Exit without cd")
	fmt.Println("  /: Fuzzy search")
	fmt.Println("  d, Delete: Delete file or directory")
	fmt.Println("  y: Yank current dir")
	fmt.Println("  .: Hide hidden files")
}

func initState() *State {
	return &State{
		CurrentDir: ".",
		Files:      []FileEntry{},
		Selected:   0,
		PreviewMode: false,
		PreviewFile: nil,
		SearchQuery: "",
		SearchResults: []FileEntry{},
		SearchIndex: 0,
		HideHidden: false,
		Border: false,
		Icons: false,
		DirOnly: false,
		ExitWithoutCD: false,
	}
}

func loadEnvVars() {
	// Load environment variables
	// EDITOR or WALK_EDITOR
	// WALK_OPEN_WITH
	// WALK_REMOVE_CMD
	// WALK_MAIN_COLOR
	// WALK_STATUS_BAR
}

func loadIcons() {
	// Load icons from etc/icons
}

func loadStatusBar() {
	// Load status bar expression
}

func loadOpenWith() {
	// Load open with commands
}

func loadRemoveCmd() {
	// Load remove command
}

func loadMainColor() {
	// Load main color
}

func run(state *State) {
	// Get initial directory
	if len(os.Args) > 1 {
		state.CurrentDir = os.Args[1]
	}

	// Load files
	loadFiles(state)

	// Start the main loop
	if state.SearchQuery != "" {
		// Start with fuzzy search
		state.SearchResults = fuzzySearch(state.Files, state.SearchQuery)
		state.SearchIndex = 0
	}

	// Set up input reader
	reader := bufio.NewReader(os.Stdin)

	for {
		// Render the UI
		render(state, reader)

		// Read input
		ch, err := reader.ReadByte()
		if err != nil {
			break
		}

		// Handle input
		handleInput(state, reader, ch)
	}
}

func loadFiles(state *State) {
	entries, err := os.ReadDir(state.CurrentDir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}

		info, err := entry.Info()
		if err != nil {
			continue
		}

		name := entry.Name()
		isHidden := strings.HasPrefix(name, ".")

		if state.HideHidden && isHidden {
			continue
		}

		if state.DirOnly && !entry.IsDir() {
			continue
		}

		file := FileEntry{
			Name:     name,
			IsDir:    entry.IsDir(),
			IsHidden: isHidden,
			Size:     info.Size(),
			Mode:     info.Mode(),
			ModTime:  info.ModTime(),
		}

		state.Files = append(state.Files, file)
	}

	// Sort files
	sort.Slice(state.Files, func(i, j int) bool {
		if state.Files[i].IsDir != state.Files[j].IsDir {
			return state.Files[i].IsDir
		}
		return state.Files[i].Name < state.Files[j].Name
	})
}

func handleInput(state *State, reader *bufio.Reader, ch byte) {
	switch ch {
	case '\r', '\n':
		// Enter key
		if state.PreviewMode {
			state.PreviewMode = false
		} else {
			enterDirectory(state)
		}
	case '\x7f', 127:
		// Backspace
		backspace(state)
	case ' ':
		// Space
		togglePreview(state)
	case 27:
		// Escape
		escape(state)
	case 'q':
		// q
		escape(state)
	case '\x03':
		// Ctrl+C
		state.ExitWithoutCD = true
	case '/':
		// Fuzzy search
		fuzzySearchStart(state)
	case 'd', 8:
		// Delete
		deleteFile(state)
	case 'y':
		// Yank
		yank(state)
	case '.':
		// Hide hidden files
		state.HideHidden = !state.HideHidden
		loadFiles(state)
