func handleInput(state *State, reader *bufio.Reader, ch byte) {
	switch ch {
	case '\r', '\n':
		// Enter key
		if state.PreviewMode {
			state.PreviewMode = false
		} else {
			enterDirectory(state)
		}
	case '\x7f', 127:
		// Backspace
		backspace(state)
	case ' ':
		// Space
		togglePreview(state)
	case 27:
		// Escape
		escape(state)
	case 'q':
		// q
		escape(state)
	case '\x03':
		// Ctrl+C
		state.ExitWithoutCD = true
	case '/':
		// Fuzzy search
		fuzzySearchStart(state)
	case 'd', 8:
		// Delete
		deleteFile(state)
	case 'y':
		// Yank
		yank(state)
