	SearchQuery  string
	SearchResults []FileEntry
	SearchIndex  int
	HideHidden   bool
	Border       bool
	Icons        bool
	DirOnly      bool
	ExitWithoutCD bool
}

func main() {
	state := initState()

	// Parse flags
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--icons":
			state.Icons = true
		case "--dir-only":
			state.DirOnly = true
		case "--hide-hidden":
			state.HideHidden = true
		case "--preview":
			state.PreviewMode = true
		case "--with-border":
			state.Border = true
		case "--fuzzy":
			state.SearchQuery = ""
			state.SearchResults = state.Files
			state.SearchIndex = 0
		case "--help":
			printHelp()
			os.Exit(0)
