{"command": "cat > /workspace/main.go << 'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

const Version = "1.13.0"

type FileEntry struct {
	Name     string
	IsDir    bool
	IsHidden bool
	Size     int64
	Mode     os.FileMode
	ModTime  time.Time
}

type State struct {
	CurrentDir   string
	Files        []FileEntry
	Selected     int
	PreviewMode  bool
	PreviewFile  *FileEntry
	SearchQuery  string
	SearchResults []FileEntry
	SearchIndex  int
	HideHidden   bool
	Border       bool
	Icons        bool
	DirOnly      bool
	ExitWithoutCD bool
}

func main() {
	state := initState()

	// Parse flags
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--icons":
			state.Icons = true
		case "--dir-only":
			state.DirOnly = true
		case "--hide-hidden":
			state.HideHidden = true
		case "--preview":
			state.PreviewMode = true
		case "--with-border":
			state.Border = true
		case "--fuzzy":
			state.SearchQuery = ""
			state.SearchResults = state.Files
			state.SearchIndex = 0
		case "--help":
			printHelp()
			os.Exit(0)
		case "--version":
			fmt.Println("walk version", Version)
			os.Exit(0)
		}
	}

	// Check for TTY
	if !hasTTY() {
		fmt.Println("walk: terminal required")
		os.Exit(1)
	}

	// Get initial directory
	if len(os.Args) > 1 {
		state.CurrentDir = os.Args[1]
	}

	// Load files
	loadFiles(state)

	// Start the main loop
	if state.SearchQuery != "" {
		state.SearchResults = fuzzySearch(state.Files, state.SearchQuery)
		state.SearchIndex = 0
	}

	// Set up input reader
	reader := bufio.NewReader(os.Stdin)

	for {
		// Render the UI
		render(state, reader)

		// Read input
		ch, err := reader.ReadByte()
		if err != nil {
			break
		}

		// Handle input
		handleInput(state, reader, ch)
	}
}

func hasTTY() bool {
	return os.IsTerminal(syscall.Stdin)
}

