func initState() *State {
	return &State{
		CurrentDir: ".",
		Files:      []FileEntry{},
		Selected:   0,
		PreviewMode: false,
		PreviewFile: nil,
		SearchQuery: "",
		SearchResults: []FileEntry{},
		SearchIndex: 0,
		HideHidden: false,
		Border: false,
		Icons: false,
		DirOnly: false,
		ExitWithoutCD: false,
	}
}

func loadFiles(state *State) {
	entries, err := os.ReadDir(state.CurrentDir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}

		info, err := entry.Info()
		if err != nil {
			continue
		}

		name := entry.Name()
		isHidden := strings.HasPrefix(name, ".")

		if state.HideHidden && isHidden {
			continue
		}

		if state.DirOnly && !entry.IsDir() {
			continue
		}

		file := FileEntry{
			Name:     name,
			IsDir:    entry.IsDir(),
			IsHidden: isHidden,
			Size:     info.Size(),
			Mode:     info.Mode(),
			ModTime:  info.ModTime(),
		}

		state.Files = append(state.Files, file)
	}

	// Sort files
	sort.Slice(state.Files, func(i, j int) bool {
		if state.Files[i].IsDir != state.Files[j].IsDir {
			return state.Files[i].IsDir
		}
		return state.Files[i].Name < state.Files[j].Name
	})
}

func handleInput(state *State, reader *bufio.Reader, ch byte) {
	switch ch {
	case '\r', '\n':
		// Enter key
		if state.PreviewMode {
			state.PreviewMode = false
		} else {
			enterDirectory(state)
		}
	case '\x7f', 127:
		// Backspace
		backspace(state)
	case ' ':
		// Space
		togglePreview(state)
	case 27:
		// Escape
		escape(state)
	case 'q':
		// q
		escape(state)
	case '\x03':
		// Ctrl+C
		state.ExitWithoutCD = true
	case '/':
		// Fuzzy search
		fuzzySearchStart(state)
	case 'd', 8:
		// Delete
		deleteFile(state)
	case 'y':
		// Yank
		yank(state)
	case '.':
		// Hide hidden files
		state.HideHidden = !state.HideHidden
		loadFiles(state)
	case 'u':
		// Undo
		undo(state)
	case 'h', 'j', 'k', 'l':
		// hjkl navigation
		hjklNavigation(state, ch)
	case 21:
		// Ctrl+[
		jumpToStart(state)
	case 22:
