		if state.HideHidden && isHidden {
			continue
		}

		if state.DirOnly && !entry.IsDir() {
			continue
		}

		file := FileEntry{
			Name:     name,
			IsDir:    entry.IsDir(),
			IsHidden: isHidden,
			Size:     info.Size(),
			Mode:     info.Mode(),
			ModTime:  info.ModTime(),
